const body = $input.first().json.body;
const entry = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const contact = change?.contacts?.[0];

if (!message) return [{ json: { skip: true } }];

const base = {
  skip: false,
  isUnsupported: false,
  isInteractive: false,
  phoneNumber: message.from,
  phoneNumberId: change.metadata.phone_number_id,
  contactName: contact?.profile?.name || 'Student',
  timestamp: message.timestamp,
};

if (message.type === 'interactive') {
  const r = message.interactive?.list_reply || message.interactive?.button_reply;
  return [{ json: { ...base, isInteractive: true, selectionId: r?.id || '', selectionTitle: r?.title || '', query: r?.title || '' } }];
}

if (message.type !== 'text') {
  return [{ json: { ...base, isUnsupported: true, response: 'I only understand text messages and menu selections. Please type your query.' } }];
}

return [{ json: { ...base, query: message.text.body } }];

const input = $input.first().json;
const id = (input.selectionId || '').trim();

const sectionLabels = {
  'Sec-SD': 'Software Dev', 'Sec-SA': 'AI & ML',
  'Sec-SC': 'Cyber Security', 'Sec-SI': 'IBM',
  'Sec-SX': 'Xebia', 'Sec-SK': 'Section SK',
};

// SECTION|TAB — user picked a section, now show day picker
if (id.startsWith('SECTION|')) {
  const tab = id.replace('SECTION|', '');
  return [{ json: {
    ...input,
    detectedSection: tab,
    detectedSectionName: sectionLabels[tab] || tab,
    detectedDay: null,
    isTimestableRequest: false,
    fullDayRange: `${tab}!A:H`,
  }}];
}

// TAB|Day — user picked a day, fetch timetable
const parts = id.split('|');
if (parts.length === 2 && parts[0] && parts[1]) {
  const tab = parts[0], day = parts[1];
  return [{ json: {
    ...input,
    detectedSection: tab,
    detectedSectionName: sectionLabels[tab] || tab,
    detectedDay: day,
    originalQuery: `${tab} ${day}`,
    isTimestableRequest: true,
    fullDayRange: `${tab}!A:H`,
  }}];
}

return [{ json: { ...input, isTimestableRequest: false, detectedSection: null } }];

const input = $input.first().json;
const query = (input.query || '').trim();
const queryLower = query.toLowerCase();

const sectionMap = [
  { keywords: ['sec-sk', 'sec sk', 'section sk', 'sk'], tab: 'Sec-SK', name: 'Section SK' },
  { keywords: ['software development', 'software dev', 'sd'], tab: 'Sec-SD', name: 'Software Dev' },
  { keywords: ['aiml', 'ai', 'artificial intelligence', 'machine learning', 'ml'], tab: 'Sec-SA', name: 'AI & ML' },
  { keywords: ['cyber security', 'cybersec', 'cyber', 'cys'], tab: 'Sec-SC', name: 'Cyber Security' },
  { keywords: ['ibm'], tab: 'Sec-SI', name: 'IBM' },
  { keywords: ['xebia'], tab: 'Sec-SX', name: 'Xebia' },
];

let detectedSection = null, detectedSectionName = null;
for (const m of sectionMap) {
  if (m.keywords.some(k => queryLower.includes(k))) { detectedSection = m.tab; detectedSectionName = m.name; break; }
}

const dayMap = { 'monday':'Monday','mon':'Monday','tuesday':'Tuesday','tue':'Tuesday','wednesday':'Wednesday','wed':'Wednesday','thursday':'Thursday','thu':'Thursday','friday':'Friday','fri':'Friday','saturday':'Saturday','sat':'Saturday' };
const now = new Date();
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let detectedDay = null;

if (['today','aaj'].some(w => queryLower.includes(w))) {
  detectedDay = dayNames[now.getDay()];
} else if (['tomorrow','kal'].some(w => queryLower.includes(w))) {
  const tmp = new Date(now); tmp.setDate(tmp.getDate()+1); detectedDay = dayNames[tmp.getDay()];
} else {
  for (const [k,v] of Object.entries(dayMap)) { if (queryLower.includes(k)) { detectedDay = v; break; } }
}

const holidays = [
  { date: '2026-01-26', event: 'Republic Day' }, { date: '2026-03-04', event: 'Holi' },
  { date: '2026-03-21', event: 'Eid-Ul-Fitr' }, { date: '2026-08-15', event: 'Independence Day' },
  { date: '2026-10-02', event: 'Gandhi Jayanti' }, { date: '2026-11-08', event: 'Deepawali' },
];
const todayStr = now.toISOString().split('T')[0];
let isHoliday = false, holidayEvent = null;
if (['today','aaj'].some(w => queryLower.includes(w))) {
  const h = holidays.find(h => h.date === todayStr);
  if (h) { isHoliday = true; holidayEvent = h.event; }
}

return [{ json: {
  originalQuery: query,
  phoneNumber: input.phoneNumber,
  phoneNumberId: input.phoneNumberId,
  contactName: input.contactName,
  detectedSection,
  detectedSectionName,
  detectedDay,
  isHoliday,
  holidayEvent,
  needsSection: !detectedSection,
  hasDay: !!detectedDay,
  fullDayRange: detectedSection ? `${detectedSection}!A:H` : null,
} }];

const input = $input.first().json;
return [{ json: {
  phoneNumber: input.phoneNumber,
  phoneNumberId: input.phoneNumberId,
  response: `🎉 *No classes today!*\n\n📅 Today is a holiday: *${input.holidayEvent}*\n\nEnjoy your day! 🌟`,
} }];

const rows = $input.all().map(i => i.json);

let preprocessed = {};
try { preprocessed = $('Query Preprocessor').first().json; } catch(_) {}
if (!preprocessed.detectedSection) {
  try {
    const ps = $('Parse Selection').first().json;
    preprocessed = { ...ps, originalQuery: ps.query || ps.selectionTitle || ps.detectedSection + ' ' + ps.detectedDay };
  } catch(_) {}
}

const systemInstruction = 'You are a timetable assistant for JECRC University, Jaipur. Format the provided timetable data into a clear, readable WhatsApp message. Use emojis. Be concise. Mark empty slots as Free Period.';

const userPrompt = [
  `Student asked: "${preprocessed.originalQuery || 'timetable'}"`,
  `Section: ${preprocessed.detectedSectionName || preprocessed.detectedSection}`,
  `Day requested: ${preprocessed.detectedDay || 'Full week'}`,
  '',
  'Timetable data (JSON):',
  JSON.stringify(rows, null, 2),
  '',
  'Format this into a clear, student-friendly WhatsApp message.',
].join('\n');

const geminiBody = JSON.stringify({
  system_instruction: { parts: [{ text: systemInstruction }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.1, maxOutputTokens: 512 },
});

const geminiKey = $env.GEMINI_API_KEY || '';

return [{ json: { geminiBody, geminiKey, preprocessed } }];

const geminiResponse = $input.first().json;
const preprocessed = $('Prepare Gemini Request').first().json.preprocessed;

let response = '';
try {
  response = geminiResponse.candidates[0].content.parts[0].text || '';
} catch(e) {
  response = 'Sorry, I could not retrieve the timetable. Please try again with your section and day (e.g. "SD Monday").';
}

if (!response.trim()) {
  response = 'Sorry, I could not generate a response. Please try again.';
}

return [{ json: {
  response,
  phoneNumber: preprocessed.phoneNumber,
  phoneNumberId: preprocessed.phoneNumberId,
} }];
